// Every bilingual text of the hand-written data (src/data/custom/**/*.json) also carries its Spanish (`es`), with the
// official terms of SP_SRD_CC_v5.2.1.pdf. effects/magic-items.json and summaries-items.json are generated by
// tools/build_magic_item_effects.py, which holds their Spanish.
import { readdirSync, readFileSync, statSync } from 'node:fs'
import { join, relative } from 'node:path'
import { describe, expect, it } from 'vitest'

const CUSTOM = join(__dirname, '..', 'data', 'custom')
// Translated separately (their own coverage tests).
const SKIP = new Set(['summaries.json', 'summaries-spells.json'])

function jsonFiles(dir: string): string[] {
  return readdirSync(dir).flatMap((name) => {
    const p = join(dir, name)
    if (statSync(p).isDirectory()) return jsonFiles(p)
    return name.endsWith('.json') && !SKIP.has(name) ? [p] : []
  })
}

function missingEs(node: unknown, path: string, out: string[]): void {
  if (Array.isArray(node)) {
    node.forEach((v, i) => missingEs(v, `${path}[${i}]`, out))
  } else if (node && typeof node === 'object') {
    const o = node as Record<string, unknown>
    if (typeof o.en === 'string' && typeof o.fr === 'string') {
      if (typeof o.es !== 'string' || !o.es.trim()) out.push(`${path}: ${o.en}`)
    }
    for (const [k, v] of Object.entries(o)) missingEs(v, `${path}.${k}`, out)
  }
}

describe('hand-written data in Spanish', () => {
  const files = jsonFiles(CUSTOM)

  it('finds the custom data files', () => {
    expect(files.length).toBeGreaterThan(15)
  })

  it.each(files.map((f) => [relative(CUSTOM, f).replace(/\\/g, '/'), f]))(
    '%s: every {en, fr} has a non-empty es',
    (_name, file) => {
      const missing: string[] = []
      missingEs(JSON.parse(readFileSync(file, 'utf8')), '$', missing)
      expect(missing).toEqual([])
    },
  )
})
